<?php
$search=mb_substr((string)($_GET['q']??''),0,100);
$category=(int)($_GET['category']??0);$page=max(1,min(10000,(int)($_GET['p']??1)));$offset=($page-1)*24;
$isAlphaLanding=alphaTheme()&&$search===''&&!$category&&$page===1&&!isset($_GET['all']);
$premiumLanding=$isAlphaLanding&&storeTheme()==='alpha-premium';
$alphaCollection=$premiumLanding&&($_GET['collection']??'')==='new'?'new':'featured';
$limit=$isAlphaLanding?8:24;
$where='p.active=1';$args=[];
if($search!==''){$where.=' AND (p.name LIKE ? OR p.sku LIKE ?)';$args[]='%'.$search.'%';$args[]='%'.$search.'%';}
if($category){$where.=' AND p.category_id=?';$args[]=$category;}
if(!isset($_GET['all'])&&$search===''&&!$category&&$alphaCollection!=='new')$where.=' AND p.featured=1';
$sort=match((string)($_GET['sort']??'')){'price_asc'=>'p.price ASC,p.id DESC','price_desc'=>'p.price DESC,p.id DESC','name'=>'p.name ASC,p.id DESC',default=>'p.created_at DESC,p.id DESC'};
if($isAlphaLanding&&$alphaCollection==='featured'&&empty($_GET['sort']))$sort="CASE p.sku WHEN 'ALPHA-DEMO-007' THEN 0 WHEN 'ALPHA-DEMO-002' THEN 1 WHEN 'ALPHA-DEMO-009' THEN 2 WHEN 'ALPHA-DEMO-001' THEN 3 ELSE 4 END,p.id DESC";
$total=(int)query("SELECT COUNT(*) FROM products p WHERE $where",$args)->fetchColumn();
$products=query("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE $where ORDER BY $sort LIMIT $limit OFFSET $offset",$args)->fetchAll();
$categories=query('SELECT c.*, (SELECT COUNT(*) FROM products p WHERE p.category_id=c.id AND p.active=1) product_count, (SELECT image_url FROM products p WHERE p.category_id=c.id AND p.active=1 ORDER BY p.id DESC LIMIT 1) image_url FROM categories c ORDER BY c.sort_order,c.name')->fetchAll();
$slides=heroProducts();
$isAlphaLanding=alphaTheme()&&$search===''&&!$category&&$page===1&&!isset($_GET['all']);
if($isAlphaLanding)alphaHero();
?>
<?php if(!alphaTheme()&&$search===''&&!$category&&$page===1):?>
<section class="showcase campaign-showcase editorial-showcase" aria-label="Istaknuti proizvodi" aria-roledescription="rotirajući prikaz" data-carousel>
<?php if($slides):foreach($slides as $index=>$slide):?>
<article class="hero-slide <?=!empty($slide['hero_banner_url'])?'hero-banner-slide':'hero-auto-slide'?>" data-slide <?= $index?'hidden':'' ?> aria-label="<?=($index+1).' od '.count($slides)?>">
<?php if(!empty($slide['hero_banner_url'])):?><h1 class="sr-only"><?=e($slide['name'])?></h1><img class="campaign-banner" src="<?=e(imageSource($slide['hero_banner_url']))?>" alt="<?=e($slide['name'].' · '.money((float)$slide['price']))?>" <?=!$index?'fetchpriority="high"':'loading="lazy"'?>><a class="campaign-cta" href="<?=e(productLink((int)$slide['id']))?>">Pogledaj ponudu <span class="sr-only">— <?=e($slide['name'])?></span><span aria-hidden="true">↗</span></a><?php else:?><div class="hero-copy"><span class="hero-kicker"><i></i> IZDVAJAMO ZA VAS</span><h1><?=e($slide['name'])?></h1><p class="hero-description"><?=e(excerptText((string)$slide['description'],110))?></p><div class="hero-purchase"><?php renderPrice($slide);?><a class="btn" href="<?=e(productLink((int)$slide['id']))?>">Pogledaj proizvod <span aria-hidden="true">↗</span></a></div><p class="hero-note">Dostupnost i opcije dostave na stranici proizvoda.</p></div>
<a class="hero-art" href="<?=e(productLink((int)$slide['id']))?>" aria-label="<?=e('Pogledaj '.$slide['name'])?>"><img src="<?=e(imageSource($slide['image_url']))?>" alt="<?=e($slide['name'])?>" <?=!$index?'fetchpriority="high"':'loading="lazy"'?>></a><?php $detailImages=array_values(array_unique(array_filter(query('SELECT image_url FROM product_images WHERE product_id=? ORDER BY sort_order,id',[$slide['id']])->fetchAll(PDO::FETCH_COLUMN),fn($src)=>$src!==$slide['image_url'])));if($detailImages):?><div class="hero-detail-images" aria-label="Detalji artikla"><?php foreach(array_slice($detailImages,0,2) as $detailIndex=>$src):?><a href="<?=e(productLink((int)$slide['id']))?>" aria-label="<?=e('Pogledaj detalj '.($detailIndex+1).' artikla '.$slide['name'])?>"><img src="<?=e(imageSource($src))?>" alt="<?=e('Detalj artikla: '.$slide['name'])?>" loading="lazy"></a><?php endforeach;?></div><?php endif;endif;?>
</article><?php endforeach;else:?>
<div class="hero-slide intro-slide"><div class="hero-copy"><span class="hero-kicker"><i></i> DOBRO DOŠLI</span><h1><?=e(setting('hero_title'))?></h1><p class="hero-description"><?=e(setting('hero_text'))?></p><a class="btn" href="#ponuda">Istraži ponudu <span aria-hidden="true">↗</span></a></div><div class="hero-art"><img src="assets/product-placeholder.svg" alt=""></div></div>
<?php endif;?>
<?php if(count($slides)>1):?><div class="carousel-controls" data-carousel-controls hidden><div class="carousel-dots"><?php foreach($slides as $i=>$slide):?><button class="carousel-dot" data-slide-index="<?=$i?>" aria-label="<?=e('Prikaži '.$slide['name'])?>" aria-pressed="<?=$i?'false':'true'?>"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></button><?php endforeach;?></div><div><button class="icon-button" data-carousel-pause aria-label="Zaustavi automatsku izmjenu">Ⅱ</button><button class="icon-button" data-carousel-prev aria-label="Prethodni proizvod">←</button><button class="icon-button" data-carousel-next aria-label="Sljedeći proizvod">→</button></div><span class="sr-only" data-carousel-status aria-live="polite"></span></div><?php endif;?></section>
<div class="service-strip editorial-services"><div><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="m16 3 12 6v14l-12 6-12-6V9zM4 9l12 6 12-6M16 15v14M10 6l12 6"/></svg><p><strong>Vlastiti lager</strong><small>Jasna dostupnost artikala</small></p></div><div><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M3 23V7h17v16M20 12h5l5 7v4h-3M8 23h14M3 23h1"/><circle cx="7" cy="24" r="3"/><circle cx="25" cy="24" r="3"/></svg><p><strong>Dostava na adresu</strong><small>Odaberite način dostave</small></p></div><div><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="4" y="8" width="24" height="19" rx="3"/><path d="m6 8 17-5v5M28 15h-9v7h9"/><circle cx="22" cy="18.5" r=".8"/></svg><p><strong>Plaćanje pouzećem</strong><small>Jednostavna kupovina</small></p></div></div>
<?php $homeCategories=array_filter($categories,fn($c)=>(bool)$c['show_on_home']);if($homeCategories):?><section class="category-section"><div class="section-heading"><div><p class="eyebrow">PRONAĐITE NEŠTO ZA SEBE</p><h2>Kupujte po kategorijama</h2></div><a class="text-link" href="?all=1#ponuda">Cijela ponuda ↗</a></div><div class="category-grid"><?php foreach($homeCategories as $c):?><a class="category-card" href="?category=<?=$c['id']?>#ponuda"><img src="<?=e(imageSource($c['image_url']))?>" alt="" loading="lazy"><span><strong><?=e($c['name'])?></strong><small><?=(int)$c['product_count']?> artikala</small></span><b aria-hidden="true">↗</b></a><?php endforeach;?></div></section><?php endif;endif;?>
<?php if(alphaTheme()&&setting('alpha_demo_notice','0')==='1'):?><p class="alpha-demo-notice"><strong>Testna ponuda.</strong> Probni artikli, cijene i zalihe.</p><?php endif;?>
<section id="ponuda" class="catalog-section"><div class="section-heading"><div><p class="eyebrow"><?=$premiumLanding?'ODABRANO ZA VAŠU RADIONICU':'PAŽLJIVO ODABRANA PONUDA'?></p><h2><?=$category?e((string)(query('SELECT name FROM categories WHERE id=?',[$category])->fetchColumn()?:'Kategorija')):($search!==''?'Rezultati pretrage':($alphaCollection==='new'?'Novo u ponudi':(isset($_GET['all'])?'Svi proizvodi':'Izdvojeno iz ponude')))?></h2></div><?php if($premiumLanding):?><a class="alpha-view-all" href="?all=1#ponuda">Pogledaj sve <span aria-hidden="true">→</span></a><?php else:?><span class="result-count"><?=$total?> artikala</span><?php endif;?></div>
<?php if($premiumLanding):?><nav class="alpha-collections" aria-label="Izbor ponude"><a href="./#ponuda" <?=$alphaCollection==='featured'?'aria-current="page"':''?>>Izdvojeno</a><a href="?collection=new#ponuda" <?=$alphaCollection==='new'?'aria-current="page"':''?>>Novo u ponudi</a><a href="?all=1#ponuda">Svi artikli <span aria-hidden="true">→</span></a></nav><?php endif;?>
<?php if(!$premiumLanding):?><?php if(alphaTheme()):?><details class="alpha-filter-box" <?=!$isAlphaLanding?'open':''?>><summary>Pretraga i filteri proizvoda</summary><?php endif;?><form method="get" class="catalog-filters"><label class="sr-only" for="catalog-q">Pretraga artikala</label><input id="catalog-q" name="q" placeholder="Šta tražite?" value="<?=e($search)?>"><label class="sr-only" for="catalog-category">Kategorija</label><select id="catalog-category" name="category"><option value="">Sve kategorije</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$category===(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><label class="sr-only" for="catalog-sort">Redoslijed</label><select id="catalog-sort" name="sort"><?php foreach([''=>'Najnovije','price_asc'=>'Cijena: niža prvo','price_desc'=>'Cijena: viša prvo','name'=>'Naziv: A–Z'] as $value=>$label):?><option value="<?=$value?>" <?=($_GET['sort']??'')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select><label class="filter-check"><input type="checkbox" name="all" value="1" <?=isset($_GET['all'])?'checked':''?>> Cijela ponuda</label><button>Prikaži</button></form><?php if(alphaTheme()):?></details><?php endif;?><?php endif;?>
<div class="product-grid"><?php foreach($products as $p)productCard($p);?></div>
<?php if(!$products):?><div class="empty-state"><span aria-hidden="true">⌕</span><h3>Trenutno nema artikala za ovaj izbor.</h3><p>Pokušajte drugu kategoriju ili pregledajte cijelu ponudu.</p><a class="btn" href="?all=1#ponuda">Svi artikli</a></div><?php endif;?>
<?php if(!$isAlphaLanding):?><nav class="pagination" aria-label="Stranice kataloga"><?php if($page>1):?><a class="btn secondary" href="?<?=e(http_build_query(array_merge($_GET,['p'=>$page-1])))?>#ponuda">← Prethodna</a><?php endif;?><span>Stranica <?=$page?> / <?=max(1,(int)ceil($total/24))?></span><?php if($offset+24<$total):?><a class="btn secondary" href="?<?=e(http_build_query(array_merge($_GET,['p'=>$page+1])))?>#ponuda">Sljedeća →</a><?php endif;?></nav><?php else:?><div class="alpha-show-all"><a class="btn" href="?all=1#ponuda">Pogledajte sve artikle →</a></div><?php endif;?></section><?php if($isAlphaLanding){if(storeTheme()==='alpha-premium')alphaLowerHome();else alphaPromotion();}?>
